import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";


// --------------------------------------------------
// Placement Event
//
// Other systems listen for this:
// - spawn-system
// - collectible-spawn-system
// --------------------------------------------------

export const OBJECT_PLACED_EVENT =
  "OBJECT_PLACED";



// --------------------------------------------------
// Placement System
//
// Responsibilities:
// - Receive screen tap
// - Raycast into AR world
// - Spawn DriveZone prefab
// - Store driveZoneEid
// --------------------------------------------------


ecs.registerComponent({

  name:"placement-system",


  schema:{

    driveZonePrefab:ecs.eid,

  },



  stateMachine:({world,eid,schemaAttribute,defineState})=>{


    defineState("waiting")

    .initial()


    .onEnter(()=>{


      console.log(
        "[Placement] Waiting for tap"
      );



      world.events.addListener(

        world.events.globalId,

        ecs.input.SCREEN_TOUCH_START,


        (event:any)=>{


          placeDriveZone(

            world,

            schemaAttribute.get(eid),

            event

          );


        }


      );


    });


  },


});





// --------------------------------------------------
// Spawn DriveZone
// --------------------------------------------------

function placeDriveZone(

  world:ecs.World,

  schema:any,

  event:any

){


  //---------------------------------------
  // Prevent duplicate placement
  //---------------------------------------

  if(gameData.driveZonePlaced)
    return;



  //---------------------------------------
  // Get touch world position
  //---------------------------------------

  const position =
    event.data?.worldPosition;



  if(!position){

    console.warn(
      "[Placement] No world position"
    );

    return;

  }



  console.log(
    "[Placement] Hit:",
    position
  );




  //---------------------------------------
  // Spawn DriveZone
  //---------------------------------------

  const driveZone =

    world.createEntity(

      schema.driveZonePrefab

    );



  world.transform.setWorldPosition(

    driveZone,

    {

      x:position.x,

      y:position.y,

      z:position.z,

    }

  );



  //---------------------------------------
  // Save state
  //---------------------------------------

  gameData.driveZoneEid =
    driveZone;


  gameData.driveZonePlaced =
    true;



  console.log(

    "[Placement] DriveZone placed successfully.",

    driveZone

  );



  //---------------------------------------
  // Notify systems
  //---------------------------------------

  world.events.dispatchEvent(

    world.events.globalId,

    OBJECT_PLACED_EVENT,

    {

      eid:driveZone,

    }

  );


}
